#include <stdio.h>
int del(int a[], int n, int x) {
    int p, i;
    p = 0;
    while (x >= a[p] && p < n)
        p++;
    for (i = p - 1; i < n; i++)
        a[i] = a[i + 1];
    n = n - 1;
    return n;
}
int main() {
