#include <string.h>

int my_strcmp(const char *a, const char *b) {
    while (*a != '\0' && *a == *b) {
        a++;
        b++;
    }
    return (unsigned char)*a - (unsigned char)*b;
}

int main(void) {
    char a[256], b[256];
    fgets(a, sizeof(a), stdin);
    a[strcspn(a, "\n")] = 0;
